import React from 'react';
import { IconButton, IconButtonProps, Stack } from '@mui/material';
import { DarkMode, LightMode } from '@mui/icons-material';
import { ThemeContext } from '../hooks/useColorSchema';


const Button = (props: IconButtonProps) => {
    return (
        <IconButton
            sx={{
                p: "3px",
                borderRadius: "6px",

                ...(props.disabled ? {
                    // backgroundColor: (theme) => theme.palette.background.paper,
                } : {
                    backgroundColor: (theme) => theme.palette.background.default,
                    boxShadow: theme => theme.shadows[10]
                })
            }}
            {...props}
        />
    )
}

function ToggleThemeStack() {
    const { darkMode, toggleDarkMode } = React.useContext(ThemeContext);

    return (
        <Stack
            direction="row"
            gap={3}
            sx={{
                width: "min-content",
                height: "min-content",
                justifyContent: "flex-start",
                alignItems: "center",
                padding: "9px",
                backgroundColor: (theme) => theme.palette.background.paper,
                overflow: "visible",
                alignContent: "center",
                flexWrap: "nowrap",
                borderRadius: "14px",
                my: 0.5
            }}
        >
            <Button
                onClick={toggleDarkMode}
                children={<LightMode />}
                disabled={!darkMode}
            />
            <Button
                onClick={toggleDarkMode}
                children={<DarkMode />}
                disabled={darkMode}
            />
        </Stack >
    );

};

export default ToggleThemeStack;
